'use client';
import React from 'react';

import * as Picker from 'emoji-picker-react/primitives';

// Name autocomplete: feed the picker's search box from your own input
// through `searchValue`, and replace the `:token` in `onEmojiClick`.
// The hint reads the same state through useActiveEmoji/useSearchState.
export type PickerExampleProps = {
  /** The picker root: Picker.Root, or a styled() wrapper of it. */
  Root?: React.ComponentType<Picker.RootProps>;
  className?: string;
  /** Current `:token` query, without the colon. Shows the full grid when empty. */
  searchValue?: string;
  /** Replace the `:token` with `emoji.emoji` in your input. Defaults to a no-op. */
  onEmojiClick?: (emoji: Picker.EmojiClickData) => void;
};

function noopEmojiClick() {}

function Hint() {
  const active = Picker.useActiveEmoji();
  const { search } = Picker.useSearchState();
  return (
    <div className="typeahead-hint">
      <span className="typeahead-name">
        {active
          ? active.names[active.names.length - 1]
          : `Emoji matching “${search}”`}
      </span>
      <span>↵ insert · esc dismiss</span>
    </div>
  );
}

export function PickerExample({
  Root: RootComponent = Picker.Root,
  className,
  searchValue = '',
  onEmojiClick = noopEmojiClick,
}: PickerExampleProps) {
  return (
    <RootComponent
      appearance="default"
      className={className}
      searchValue={searchValue}
      autoFocusSearch={false}
      onEmojiClick={onEmojiClick}
    >
      <Picker.Viewport>
        <Picker.List />
        <Picker.Empty />
      </Picker.Viewport>
      <Hint />
    </RootComponent>
  );
}

/* Shortcode typeahead — an autocomplete dropdown: results only, a hint
   footer driven by useActiveEmoji(). */
.typeahead-picker {
  --epr-bg-color: #ffffff;
  --epr-text-color: #4b5563;
  --epr-highlight-color: #2563eb;
  --epr-hover-bg-color: #eff6ff;
  --epr-focus-bg-color: #dbeafe;
  --epr-category-label-height: 0px;
  --epr-emoji-size: 28px;
  --epr-emoji-padding: 6px;
  --epr-horizontal-padding: 8px;
  width: 340px;
  height: 172px;
  margin-top: 6px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 12px 28px rgb(17 24 39 / 14%);
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.typeahead-picker [data-epr-part='category-label'] {
  display: none;
}
.typeahead-picker [data-epr-part='list'] {
  padding-top: 6px;
}
.typeahead-picker [data-epr-part='emoji'] {
  border-radius: 8px;
}
.typeahead-picker .typeahead-hint {
  display: flex;
  justify-content: space-between;
  padding: 8px 12px;
  border-top: 1px solid #f3f4f6;
  color: #4b5563;
  font-size: 12px;
}
.typeahead-picker .typeahead-name::first-letter {
  text-transform: uppercase;
}

